class TestComponentDidCatch:
    """Validate error logging and state update."""

    def test_logs_error_and_info(self, error_boundary, mocker):
        """Must log both error and errorInfo to console.error."""
        console_error = mocker.patch('builtins.print')
        error = RuntimeError("critical failure")
        info = {"componentStack": "at App"}

        error_boundary.componentDidCatch(error, info)

        console_error.assert_called_once_with(
            "ErrorBoundary caught:", error, info
        )

    def test_logs_with_null_info(self, error_boundary, mocker):
        """Must handle null errorInfo gracefully."""
        console_error = mocker.patch('builtins.print')
        error = ValueError("null info")

        error_boundary.componentDidCatch(error, None)

        console_error.assert_called_once_with(
            "ErrorBoundary caught:", error, None
        )

    def test_logs_with_null_error(self, error_boundary, mocker):
        """Must handle null error gracefully."""
        console_error = mocker.patch('builtins.print')

        error_boundary.componentDidCatch(None, {"componentStack": "x"})

        console_error.assert_called_once_with(
            "ErrorBoundary caught:", None, {"componentStack": "x"}
        )

    def test_does_not_throw_on_logging_failure(self, error_boundary, mocker):
        """If console.error itself throws, componentDidCatch must not propagate."""
        console_error = mocker.patch('builtins.print', side_effect=Exception("log fail"))
        try:
            error_boundary.componentDidCatch(ValueError("x"), {})
        except Exception:
            pytest.fail("componentDidCatch should swallow logging errors")


